const input = $json.body ?? $json;
const contentId = String(input.contentId ?? '').trim();
const title = String(input.title ?? '').trim();
const suppliedMediaUrl = String(input.mediaUrl ?? '').trim();
const capturedContent = String(input.capturedContent ?? '').trim().slice(0, 100000);
const rawUrlInput = String(input.url ?? '')
  .replace(/&nbsp;|&#x20;|&#32;/gi, ' ')
  .replace(/[\u00A0\u200B-\u200D\uFEFF]/g, ' ')
  .trim();
const markdownUrl = rawUrlInput.match(/\[[^\]]*\]\((https?:\/\/[^)]+)\)/i);
const plainUrl = rawUrlInput.match(/https?:\/\/[^\s<>'"]+/i);
const rawUrl = String(markdownUrl?.[1] ?? plainUrl?.[0] ?? rawUrlInput)
  .replace(/[),.;]+$/, '')
  .trim();
const suppliedContent = String(input.content ?? '').trim();
const notes = String(input.notes ?? '').trim().slice(0, 5000);
const requestedActorId = String(input.apifyActorId ?? '').trim();
if (!contentId) throw new Error('contentId is required');
if (!title) throw new Error('title is required');
if (!rawUrl && !suppliedContent && !suppliedMediaUrl) throw new Error('Provide url, content, or mediaUrl');
if (suppliedContent.length > 100000) throw new Error('content exceeds 100000 characters');
let url = '';
let host = '';
let pathname = '';
let platform = 'web';
let isVideoSource = false;
let isFacebookShareUrl = false;
if (rawUrl) {
  const match = rawUrl.match(/^(https?):\/\/([^\s\/?#]+)([^\s?#]*)(?:\?[^\s#]*)?$/i);
  if (!match) throw new Error('Only valid http/https URLs are accepted');
  const protocol = match[1].toLowerCase();
  const authority = match[2];
  if (authority.includes('@')) throw new Error('URLs containing credentials are not accepted');
  host = authority.toLowerCase().replace(/:\d+$/, '').replace(/^www\./, '').replace(/^m\./, '').replace(/^web\./, '');
  pathname = (match[3] || '/').toLowerCase();
  url = rawUrl.replace(/#.*$/, '');
  if (protocol !== 'http' && protocol !== 'https') throw new Error('Only valid http/https URLs are accepted');
  if (host === 'youtube.com' || host.endsWith('.youtube.com') || host === 'youtu.be') {
    platform = 'youtube';
    isVideoSource = host === 'youtu.be' || pathname.startsWith('/watch') || pathname.startsWith('/shorts/') || pathname.startsWith('/live/');
  } else if (host === 'linkedin.com' || host.endsWith('.linkedin.com')) {
    platform = 'linkedin';
    isVideoSource = pathname.includes('/video/') || pathname.includes('/posts/');
  } else if (host === 'facebook.com' || host.endsWith('.facebook.com') || host === 'fb.watch') {
    platform = 'facebook';
    isFacebookShareUrl = pathname.startsWith('/share/r/') || pathname.startsWith('/share/v/');
    isVideoSource = host === 'fb.watch' || isFacebookShareUrl || pathname.startsWith('/reel/') || pathname.startsWith('/watch') || pathname.includes('/videos/');
  } else if (host === 'instagram.com' || host.endsWith('.instagram.com')) {
    platform = 'instagram';
    isVideoSource = pathname.startsWith('/reel/') || pathname.startsWith('/reels/') || pathname.startsWith('/p/');
  } else if (host === 'threads.net' || host.endsWith('.threads.net')) {
    platform = 'threads';
  } else if (host === 'tiktok.com' || host.endsWith('.tiktok.com')) {
    platform = 'tiktok';
    isVideoSource = pathname.includes('/video/') || host.startsWith('vm.') || host.startsWith('vt.');
  } else if (host === 'x.com' || host.endsWith('.x.com') || host === 'twitter.com' || host.endsWith('.twitter.com')) {
    platform = 'x';
    isVideoSource = pathname.includes('/status/');
  }
}
if (suppliedMediaUrl) {
  const mediaMatch = suppliedMediaUrl.match(/^https:\/\/([^\/?#]+)(?:[\/?#]|$)/i);
  if (!mediaMatch) throw new Error('mediaUrl must be a valid HTTPS URL');
  const mediaHost = mediaMatch[1].toLowerCase().replace(/:\d+$/, '');
  if (!(mediaHost === 'fbcdn.net' || mediaHost.endsWith('.fbcdn.net') || mediaHost === 'facebook.com' || mediaHost.endsWith('.facebook.com') || mediaHost === 'supabase.co' || mediaHost.endsWith('.supabase.co'))) throw new Error('Unsupported mediaUrl host');
}
if (requestedActorId && !/^[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+$/.test(requestedActorId)) throw new Error('Invalid Apify actor ID');
const defaultActors = { facebook: 'memo23/facebook-video-downloader' };
const apifyActorId = requestedActorId || defaultActors[platform] || '';
const requestId = `${contentId}-${Date.now()}`;
return [{ json: { contentId, title, requestId, url, host, pathname, platform, suppliedContent, suppliedMediaUrl, capturedContent, notes, apifyActorId, isVideoSource, isFacebookShareUrl, submittedAt: new Date().toISOString() } }];

let normalized;
try { normalized = $('Prepare Supplied Media').item.json; } catch { normalized = $('Normalize Apify Result').item.json; }
const transcript = typeof $json.text === 'string' ? $json.text.trim() : '';
const combined = [normalized.apifyContent, transcript ? `VIDEO TRANSCRIPT:\n${transcript}` : ''].filter(Boolean).join('\n\n').slice(0, 100000);
return [{ json: { ...normalized, apifyContent: combined, videoTranscriptFound: Boolean(transcript), extractionProvider: transcript ? `${normalized.extractionProvider}+openai_transcription` : normalized.extractionProvider } }];

const original = $('Validate and Normalize').item.json;
const raw = $json;
const records = Array.isArray(raw) ? raw : Array.isArray(raw.data) ? raw.data : Array.isArray(raw.items) ? raw.items : [raw];
const preferredKeys = ['transcript', 'videoTranscript', 'subtitles', 'captions', 'text', 'caption', 'postText', 'description', 'articleBody', 'content', 'body'];
const transcriptKeys = new Set(['transcript', 'videoTranscript', 'subtitles', 'captions']);
const mediaKeys = ['sourceMediaUrl', 'videoFileUrl', 'videoUrlHd', 'videoUrl', 'videoUrlSd', 'downloadUrl', 'download_link', 'mediaUrl', 'playAddr', 'contentUrl', 'file_url'];
const fragments = [];
const transcriptFragments = [];
const mediaUrls = [];
const addText = (key, candidate) => {
  if (typeof candidate === 'string' && candidate.trim()) { fragments.push(candidate.trim()); if (transcriptKeys.has(key)) transcriptFragments.push(candidate.trim()); }
  else if (Array.isArray(candidate)) candidate.forEach(item => {
    if (typeof item === 'string' && item.trim()) { fragments.push(item.trim()); if (transcriptKeys.has(key)) transcriptFragments.push(item.trim()); }
    else if (item && typeof item === 'object') addText(key, item.text ?? item.caption ?? item.body);
  });
};
const addMedia = candidate => {
  if (typeof candidate !== 'string') return;
  const value = candidate.trim();
  const match = value.match(/^https:\/\/([^\/?#]+)(?:[\/?#]|$)/i);
  if (!match) return;
  const host = match[1].toLowerCase().replace(/:\d+$/, '');
  if (host === 'localhost' || host.endsWith('.local') || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host)) return;
  mediaUrls.push(value);
};
const visit = (value, depth = 0) => {
  if (depth > 5 || value == null) return;
  if (Array.isArray(value)) { value.forEach(item => visit(item, depth + 1)); return; }
  if (typeof value !== 'object') return;
  for (const key of preferredKeys) addText(key, value[key]);
  for (const key of mediaKeys) addMedia(value[key]);
  for (const nested of ['data', 'result', 'results', 'post', 'posts', 'video', 'media', 'attachments']) if (value[nested]) visit(value[nested], depth + 1);
};
records.forEach(record => visit(record));
const apifyContent = [...new Set([original.capturedContent, ...fragments].filter(Boolean))].join('\n\n').slice(0, 100000);
return [{ json: { ...original, apifyContent, mediaUrl: mediaUrls[0] ?? '', videoTranscriptFound: transcriptFragments.length > 0, extractionProvider: apifyContent ? 'apify' : 'jina_fallback' } }];

const original = $('Validate and Normalize').item.json;
const extracted = original.suppliedContent || $json.apifyContent || String($json.data ?? $json.body ?? $json ?? '');
if (!extracted || extracted === '[object Object]') throw new Error('Could not extract content; submit content explicitly');
let sourceContent = extracted.slice(0, 100000);
if (!original.suppliedContent) {
  const boilerplate = [/^Markdown Content:\s*$/i, /^Log In\s*$/i, /^Forgot Account\??$/i, /^Create new account\s*$/i, /^Meta ©/i];
  sourceContent = sourceContent.split('\n').filter(line => {
    const trimmed = line.trim();
    if (boilerplate.some(pattern => pattern.test(trimmed))) return false;
    if (/facebook\.com\/(?:login|recover)\//i.test(trimmed)) return false;
    return true;
  }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
let piiRedactions = 0;
const redact = (pattern, label) => {
  sourceContent = sourceContent.replace(pattern, () => { piiRedactions += 1; return `[REDACTED ${label}]`; });
};
redact(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, 'EMAIL');
redact(/\b\d{3}-\d{2}-\d{4}\b/g, 'SSN');
redact(/\b\d{2}-\d{7}\b/g, 'EIN');
redact(/(?<!\d)(?:\+?1[ .-]?)?(?:\(\d{3}\)|\d{3})[ .-]\d{3}[ .-]\d{4}(?!\d)/g, 'PHONE');
const luhnValid = value => { const digits = value.replace(/\D/g, ''); let sum = 0; let doubleDigit = false; for (let i = digits.length - 1; i >= 0; i--) { let digit = Number(digits[i]); if (doubleDigit) { digit *= 2; if (digit > 9) digit -= 9; } sum += digit; doubleDigit = !doubleDigit; } return digits.length >= 13 && digits.length <= 19 && sum % 10 === 0; };
sourceContent = sourceContent.replace(/\b(?:\d[ -]*?){13,19}\b/g, (match, offset, full) => {
  const previous = full[offset - 1] ?? '';
  if (previous === '/' || previous === '=' || !luhnValid(match)) return match;
  piiRedactions += 1; return '[REDACTED PAYMENT NUMBER]';
});
const extractionProvider = original.suppliedContent ? 'submitted_content' : String($json.extractionProvider || 'jina');
const videoTranscriptFound = original.suppliedContent ? false : $json.videoTranscriptFound === true;
return [{ json: { ...original, sourceContent, piiRedactions, extractionProvider, videoTranscriptFound } }];

