${$json.sourceContent}` }] }], text: { format: { type: 'json_object' } }, temperature: 0.2 }) }}

parameters.jsCode:
const source = $('Prepare Source').item.json;
const response = $json;
const text = response.output_text ?? response.output?.flatMap(o => o.content ?? []).find(c => c.type === 'output_text')?.text;
if (!text) throw new Error('OpenAI returned no output text');
let draft;
try { draft = JSON.parse(text); } catch { throw new Error('OpenAI output was not valid JSON'); }
const requiredStrings = ['summary', 'accuracyReview', 'caseStudyMarkdown', 'caseStudyHTML', 'complianceNotes'];
for (const key of requiredStrings) if (typeof draft[key] !== 'string' || !draft[key].trim()) throw new Error(`OpenAI output is missing ${key}`);
draft.riskFlags = Array.isArray(draft.riskFlags) ? draft.riskFlags.map(String) : [];
if (!draft.socialPack || typeof draft.socialPack !== 'object') { draft.socialPack = {}; draft.riskFlags.push('AI omitted the social pack; fallback content was created.'); }
const social = draft.socialPack;
const fallbackPost = String(draft.summary || draft.caseStudyMarkdown || '').trim();
if (typeof social.linkedin !== 'string' || !social.linkedin.trim()) { social.linkedin = fallbackPost; draft.riskFlags.push('AI omitted LinkedIn copy; summary fallback requires review.'); }
if (typeof social.facebook !== 'string' || !social.facebook.trim()) { social.facebook = social.linkedin; draft.riskFlags.push('AI omitted Facebook copy; LinkedIn fallback requires review.'); }
if (typeof social.threads !== 'string' || !social.threads.trim()) { social.threads = fallbackPost.slice(0, 500); draft.riskFlags.push('AI omitted Threads copy; summary fallback requires review.'); }
if (typeof social.email !== 'string' || !social.email.trim()) { social.email = `Subject: ${source.title}\n\n${fallbackPost}\n\nReview the source and let us know if you would like to discuss the practical implications.`; draft.riskFlags.push('AI omitted email copy; a summary-based fallback was created.'); }
if (!Array.isArray(social.instagram) || !social.instagram.length) { social.instagram = [{ slide: 1, heading: source.title, body: fallbackPost.slice(0, 500) }]; draft.riskFlags.push('AI omitted Instagram slides; a one-slide fallback requires revision.'); }
if (source.sourceContent.length >= 200 && social.facebook.trim().split(/\s+/).length < 80) draft.riskFlags.push('Facebook output is shorter than the recommended length.');
if (source.sourceContent.length >= 200 && social.linkedin.trim().split(/\s+/).length < 120) draft.riskFlags.push('LinkedIn output is shorter than the recommended length.');
if (source.sourceContent.length >= 200 && social.instagram.length < 5) draft.riskFlags.push('Instagram output has fewer than 5 slides.');
const reelWithoutTranscript = source.platform === 'facebook' && /facebook\.com\/(?:reel|watch)/i.test(source.url) && !source.videoTranscriptFound;
if (reelWithoutTranscript) { draft.riskFlags.push('Facebook Reel transcript was unavailable; output is based on the post caption only.'); draft.riskLevel = 'HIGH'; }
else if (source.sourceContent.length < 200) { draft.riskFlags.push('Insufficient source content: verify against a full caption or transcript before approval.'); draft.riskLevel = 'HIGH'; }
else draft.riskLevel = ['LOW', 'MEDIUM', 'HIGH'].includes(String(draft.riskLevel).toUpperCase()) ? String(draft.riskLevel).toUpperCase() : draft.riskFlags.length >= 3 ? 'HIGH' : draft.riskFlags.length ? 'MEDIUM' : 'LOW';
draft.riskFlags = [...new Set(draft.riskFlags)];
draft.status = 'pending_review';
return [{ json: { contentId: source.contentId, title: source.title, requestId: source.requestId, sourceUrl: source.url, platform: source.platform, sourceContent: source.sourceContent, extractionProvider: source.extractionProvider, videoTranscriptFound: source.videoTranscriptFound, submittedAt: source.submittedAt, piiRedactions: source.piiRedactions || 0, status: 'pending_review', message: 'Draft generated successfully and sent to the review queue.', draft } }];

